-- Generated by the Tenant controller for tenant 'tenant_a' (pool mode).
CREATE DATABASE IF NOT EXISTS tenant_a;
CREATE ROLE IF NOT EXISTS tenant_a_reader;
CREATE ROLE IF NOT EXISTS tenant_a_writer;
GRANT SELECT ON tenant_a.* TO tenant_a_reader;
GRANT SELECT, INSERT, CREATE TABLE, ALTER ON tenant_a.* TO tenant_a_writer;
CREATE QUOTA IF NOT EXISTS tenant_a_quota
    FOR INTERVAL 1 hour MAX queries = 20000, read_rows = 2000000000, execution_time = 7200
    TO tenant_a_reader, tenant_a_writer;
CREATE SETTINGS PROFILE IF NOT EXISTS tenant_a_profile
    SETTINGS max_memory_usage = 8000000000, max_threads = 8 READONLY
    TO tenant_a_reader, tenant_a_writer;
-- Shared serving tables (bridge mode) use a row policy on tenant_id
CREATE ROW POLICY IF NOT EXISTS tenant_a_rp ON shared.events
    USING tenant_id = 'tenant_a' TO tenant_a_reader, tenant_a_writer;
